package com.example.transactionrecovery.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.NoSuchElementException; record ApiError(String code,String message,Instant timestamp){} @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ApiError> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiError("INVALID_REQUEST",e.getMessage(),Instant.now()));}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<ApiError> missing(NoSuchElementException e){return ResponseEntity.status(404).body(new ApiError("RESOURCE_NOT_FOUND","Resource not found",Instant.now()));}@ExceptionHandler(IllegalStateException.class) ResponseEntity<ApiError> conflict(IllegalStateException e){return ResponseEntity.status(409).body(new ApiError("INVALID_STATE_TRANSITION",e.getMessage(),Instant.now()));}}
